    assert is_supports_read(NotRead()) is False
    print("test_is_supports_read passed")

def test_is_supports_items():
    assert is_supports_items(ProxyItems()) is True
    assert is_supports_items(NotItems()) is False
    print("test_is_supports_items passed")

